1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	type ItemTypeSpec = {
47	  basePremium: number;
48	  insuranceValue: number;
49	};
50	
51	const ITEM_CATALOGUE: Record<string, ItemTypeSpec> = {
52	  sword: { basePremium: 100, insuranceValue: 1000 },
53	  amulet: { basePremium: 60, insuranceValue: 600 },
54	  staff: { basePremium: 80, insuranceValue: 800 },
55	  potion: { basePremium: 40, insuranceValue: 400 },
56	  rune: { basePremium: 25, insuranceValue: 250 },
57	  moonstone: { basePremium: 25, insuranceValue: 250 },
58	};
59	
60	const catalogueEntryFor = (item: Item): ItemTypeSpec => {
61	  const spec = ITEM_CATALOGUE[item.type];
62	
63	  if (spec === undefined) {
64	    throw new Error(`unknown item type: ${item.type}`);
65	  }
66	
67	  return spec;
68	};
69	
70	const basePremiumOf = (item: Item): number =>
71	  catalogueEntryFor(item).basePremium;
72	
73	const insuranceValueOf = (item: Item): number =>
74	  catalogueEntryFor(item).insuranceValue;
75	
76	const BLOCK_SIZE = 3;
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	const itemsGroupedByType = (items: Item[]): Item[][] => [
80	  ...items
81	    .reduce(
82	      (groupsByType, item) =>
83	        groupsByType.set(item.type, [
84	          ...(groupsByType.get(item.type) ?? []),
85	          item,
86	        ]),
87	      new Map<string, Item[]>(),
88	    )
89	    .values(),
90	];
91	
92	const formsABlock = (itemsAlike: Item[]): boolean =>
93	  itemsAlike.length === BLOCK_SIZE;
94	
95	const basePremiumOfItemsAlike = (itemsAlike: Item[]): number =>
96	  formsABlock(itemsAlike)
97	    ? BLOCK_BASE_PREMIUM
98	    : itemsAlike.reduce((total, item) => total + basePremiumOf(item), 0);
99	
100	const totalBasePremiumOf = (items: Item[]): number =>
101	  itemsGroupedByType(items).reduce(
102	    (total, itemsAlike) => total + basePremiumOfItemsAlike(itemsAlike),
103	    0,
104	  );
105	
106	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
107	
108	type Rule<Subject> = {
109	  appliesTo: (subject: Subject) => boolean;
110	  rate: number;
111	};
112	
113	const totalRateOf = <Subject,>(
114	  rules: Rule<Subject>[],
115	  subject: Subject,
116	): number =>
117	  rules.reduce(
118	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
119	    0,
120	  );
121	
122	const CURSE_SURCHARGE_RATE = 0.5;
123	const HIGH_ENCHANTMENT_THRESHOLD = 5;
124	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
125	
126	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
127	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
128	  {
129	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
130	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
131	  },
132	];
133	
134	const itemSurchargeOf = (item: Item): number =>
135	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
136	
137	const totalItemSurchargeOf = (items: Item[]): number =>
138	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
139	
140	const LOYALTY_YEARS_THRESHOLD = 2;
141	const LOYALTY_DISCOUNT_RATE = -0.2;
142	
143	// Levied on every policy, follow-ups included — not only on a customer's first.
144	const INSURANCE_SURCHARGE_RATE = 0.1;
145	
146	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
147	
148	type PolicyContext = {
149	  customer: Customer;
150	  previousContracts: number;
151	};
152	
153	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
154	  {
155	    appliesTo: ({ customer }) =>
156	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
157	    rate: LOYALTY_DISCOUNT_RATE,
158	  },
159	  {
160	    appliesTo: ({ previousContracts }) => previousContracts > 0,
161	    rate: FOLLOW_UP_DISCOUNT_RATE,
162	  },
163	];
164	
165	const totalPolicyModifierRateOf = (policy: PolicyContext): number =>
166	  INSURANCE_SURCHARGE_RATE + totalRateOf(POLICY_MODIFIER_RULES, policy);
167	
168	const quotePremium = (items: Item[], policy: PolicyContext): number => {
169	  const basePremium = totalBasePremiumOf(items);
170	
171	  return roundedUpInMHPCOsFavour(
172	    basePremium +
173	      totalItemSurchargeOf(items) +
174	      basePremium * totalPolicyModifierRateOf(policy) +
175	      PROCESSING_FEE,
176	  );
177	};
178	
179	const DEDUCTIBLE = 100;
180	const CAP_MULTIPLIER = 2;
181	
182	const insuranceSumOf = (items: Item[]): number =>
183	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
184	
185	const payoutCapOf = (items: Item[]): number =>
186	  CAP_MULTIPLIER * insuranceSumOf(items);
187	
188	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
189	const HALVED_REIMBURSEMENT_RATE = 0.5;
190	const FULL_REIMBURSEMENT_RATE = 1;
191	
192	const reimbursementRateFor = (item: Item): number =>
193	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
194	    ? HALVED_REIMBURSEMENT_RATE
195	    : FULL_REIMBURSEMENT_RATE;
196	
197	const payoutForDamage = (damage: Damage, item: Item): number =>
198	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
199	
200	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
201	
202	type ClaimResult = {
203	  payout: number;
204	  remainingCap: number;
205	};
206	
207	// Each damage entry is settled against a distinct insured item, so a policy
208	// covering one sword cannot pay out for two damaged swords.
209	type Settlement = {
210	  total: number;
211	  unclaimedItems: Item[];
212	};
213	
214	const settleDamage = (
215	  { total, unclaimedItems }: Settlement,
216	  damage: Damage,
217	): Settlement => {
218	  const claimed = unclaimedItems.findIndex(
219	    (item) => item.type === damage.itemType,
220	  );
221	
222	  if (claimed === -1) {
223	    throw new Error(`damaged item not insured: ${damage.itemType}`);
224	  }
225	
226	  return {
227	    total: total + payoutForDamage(damage, unclaimedItems[claimed]),
228	    unclaimedItems: unclaimedItems.filter((_, index) => index !== claimed),
229	  };
230	};
231	
232	const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
233	  damages.reduce(settleDamage, { total: 0, unclaimedItems: insuredItems })
234	    .total;
235	
236	// A claim never pays out more than the policy has left; whatever it does pay
237	// depletes the cap by exactly that much.
238	const drawnAgainstCap = (
239	  desiredPayout: number,
240	  remainingCap: number,
241	): ClaimResult => {
242	  const payout = Math.min(desiredPayout, remainingCap);
243	
244	  return { payout, remainingCap: remainingCap - payout };
245	};
246	
247	const settleClaim = (incident: Incident, policy: IssuedPolicy): ClaimResult =>
248	  drawnAgainstCap(
249	    totalPayoutFor(incident.damages, policy.insuredItems),
250	    policy.remainingCap,
251	  );
252	
253	// A policy, once quoted, is referred to by later claim steps via its step index.
254	// Its cap depletes as claims are paid out against it.
255	type IssuedPolicy = {
256	  insuredItems: Item[];
257	  remainingCap: number;
258	};
259	
260	// Everything a step needs to know about the steps that came before it.
261	// Policies are keyed by the index of the quote step that issued them, which is
262	// how a claim step refers to them.
263	type ScenarioHistory = {
264	  issuedPolicies: Map<number, IssuedPolicy>;
265	  results: unknown[];
266	};
267	
268	const EMPTY_HISTORY: ScenarioHistory = {
269	  issuedPolicies: new Map(),
270	  results: [],
271	};
272	
273	// Every step both records a result and leaves exactly one policy changed:
274	// a quote issues one, a claim depletes the cap of the one it draws against.
275	const withStepRecorded = (
276	  history: ScenarioHistory,
277	  policyIndex: number,
278	  policy: IssuedPolicy,
279	  result: unknown,
280	): ScenarioHistory => ({
281	  issuedPolicies: new Map(history.issuedPolicies).set(policyIndex, policy),
282	  results: [...history.results, result],
283	});
284	
285	const takeQuoteStep = (
286	  step: QuoteStep,
287	  stepIndex: number,
288	  history: ScenarioHistory,
289	  customer: Customer,
290	): ScenarioHistory =>
291	  withStepRecorded(
292	    history,
293	    stepIndex,
294	    {
295	      insuredItems: step.items,
296	      remainingCap: payoutCapOf(step.items),
297	    },
298	    {
299	      premium: quotePremium(step.items, {
300	        customer,
301	        previousContracts: history.issuedPolicies.size,
302	      }),
303	    },
304	  );
305	
306	const issuedPolicyFor = (
307	  step: ClaimStep,
308	  issuedPolicies: Map<number, IssuedPolicy>,
309	): IssuedPolicy => {
310	  const policy = issuedPolicies.get(step.policy);
311	
312	  if (policy === undefined) {
313	    throw new Error(`claim against unknown policy: ${step.policy}`);
314	  }
315	
316	  return policy;
317	};
318	
319	const takeClaimStep = (
320	  step: ClaimStep,
321	  history: ScenarioHistory,
322	): ScenarioHistory => {
323	  const policy = issuedPolicyFor(step, history.issuedPolicies);
324	  const { payout, remainingCap } = settleClaim(step.incident, policy);
325	
326	  return withStepRecorded(
327	    history,
328	    step.policy,
329	    { ...policy, remainingCap },
330	    { payout, remainingCap },
331	  );
332	};
333	
334	export const runScenario = (scenario: Scenario): ScenarioResult => {
335	  const history = scenario.steps.reduce(
336	    (soFar, step, stepIndex) =>
337	      isQuote(step)
338	        ? takeQuoteStep(step, stepIndex, soFar, scenario.customer)
339	        : takeClaimStep(step, soFar),
340	    EMPTY_HISTORY,
341	  );
342	
343	  return { results: history.results };
344	};
